# Prefix sums: O(n) build, O(1) range sum
def build_prefix(a):
    prefix = [0]
    for x in a:
        prefix.append(prefix[-1] + x)
    return prefix

def range_sum(prefix, l, r):  # inclusive l..r
    return prefix[r + 1] - prefix[l]

# In-place: move zeros to the end, keep order. O(n) time, O(1) space
def move_zeroes(nums):
    write = 0
    for read in range(len(nums)):
        if nums[read] != 0:
            nums[write] = nums[read]
            write += 1
    for i in range(write, len(nums)):
        nums[i] = 0

// In-place: move zeros to the end, keep order. O(n) time, O(1) space
static void moveZeroes(int[] nums) {
    int write = 0;
    for (int read = 0; read < nums.length; read++) {
        if (nums[read] != 0) nums[write++] = nums[read];
    }
    while (write < nums.length) nums[write++] = 0;
}

// In-place: move zeros to the end, keep order. O(n) time, O(1) space
void moveZeroes(vector<int>& nums) {
    int write = 0;
    for (int read = 0; read < (int)nums.size(); read++) {
        if (nums[read] != 0) nums[write++] = nums[read];
    }
    while (write < (int)nums.size()) nums[write++] = 0;
}

// Two Sum: O(n) time, O(n) space
function twoSum(nums, target) {
  const seen = new Map(); // value -> index
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(nums[i], i);
  }
  return [];
}

// Group anagrams: key = sorted letters
function groupAnagrams(words) {
  const groups = new Map();
  for (const w of words) {
    const key = [...w].sort().join('');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(w);
  }
  return [...groups.values()];
}

from collections import defaultdict, Counter

# Two Sum: O(n) time, O(n) space
def two_sum(nums, target):
    seen = {}  # value -> index
    for i, x in enumerate(nums):
        need = target - x
        if need in seen:
            return [seen[need], i]
        seen[x] = i
    return []

# Group anagrams: key = sorted letters
def group_anagrams(words):
    groups = defaultdict(list)
    for w in words:
        groups[''.join(sorted(w))].append(w)
    return list(groups.values())

# Anagram check with frequency counts
def is_anagram(a, b):
    return Counter(a) == Counter(b)

// Two Sum: O(n) time, O(n) space
static int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        Integer j = seen.get(target - nums[i]);
        if (j != null) return new int[] { j, i };
        seen.put(nums[i], i);
    }
    return new int[0];
}

// Two Sum: O(n) time, O(n) space
vector<int> twoSum(const vector<int>& nums, int target) {
    unordered_map<int, int> seen;
    for (int i = 0; i < (int)nums.size(); i++) {
        auto it = seen.find(target - nums[i]);
        if (it != seen.end()) return { it->second, i };
        seen[nums[i]] = i;
    }
    return {};
}
